instances.default:
Stream.concat(getProblems().stream(), getOriginalProblem() == null ? Stream.empty() : Stream.of(getOriginalProblem())).map(problem -> {
        InstanceVo instanceVo = new InstanceVo();
        instanceVo.setInstanceId(problem.getInstanceId());
        instanceVo.setInstanceName(problem.getInstanceName());
        instanceVo.setSpaceIds(problem.getSpaceIds());
        instanceVo.setObjectType(problem.getObjectType());
        instanceVo.setRelatedSpaces(problem.getRelatedSpaces());
        return instanceVo;
    }).distinct().collect(Collectors.toList())

